// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(address caller, bytes32 role, address account) public {
        // The rule: renounceRole may only ever revoke a role from the caller's own account.
        // Therefore the call must succeed only when `account == caller` (and must revert otherwise),
        // regardless of whether the role is held or not.
        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the call succeeded, it can only have been a self-renounce.
        assertTrue(!ok || account == caller);
    }
}
